from collections import deque,defaultdict
allcomps=[];seen=set()
for r in range(H):
 for c in range(W):
  v=grid[r][c]
  if v!=6 and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c));cells=[]
   while q:
    x,y=q.pop();cells.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=x+dx,y+dy
     if 0<=a<H and 0<=b<W and grid[a][b]==v and (a,b) not in seen:
      seen.add((a,b));q.append((a,b))
   allcomps.append((v,len(cells),min(x for x,y in cells),max(x for x,y in cells),min(y for x,y in cells),max(y for x,y in cells),cells))
[(v,n,(r0,r1,c0,c1),(r1-r0+1,c1-c0+1)) for v,n,r0,r1,c0,c1,cells in allcomps]
